//! 🧪️ Original source preparation retains the actual authorities and byte producer through recovery.
use semio_framework_value_native_encoding as value;
use value::*;
use semio_framework_value_native_outcome::OriginalReceivingPrimary;
use value::native_receiving::span::*;
use std::sync::{Arc,atomic::{AtomicUsize,AtomicU64,Ordering}};
#[derive(Clone)]
struct Port{source:OriginalSourceTurnIdentity,maximum:u64,quote_unwind:bool,post_unwind:bool,quotes:Arc<AtomicU64>,posts:Arc<AtomicUsize>,submitted:RetainedCloneProgress}
macro_rules! bound{()=>{type Context<'a,'b>=&'a OriginalSourceTurn where 'b:'a;fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{if c.identity()==self.source{Ok(())}else{Err(ValueError::invariant("foreign test Source"))}}fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{Some(c.identity())}}}
impl NativeAllocationAuthorityPort for Port{
 bound!();
 fn receive<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,_:NativeAllocationEvent,reply:NativeAllocationReply<'r>)->Result<NativeAllocationReplyComplete<'r>,ValueError>where 'b:'a{Ok(reply.complete(Ok(())))}
 fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,_:NativeAllocationEvent,reply:NativeAllocationReply<'r>)->Result<NativeAllocationReplyComplete<'r>,ValueError>where 'b:'a{Ok(reply.pending())}
}
impl OriginalWorkRecipient for Port{
 bound!();
 fn admits<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,reply:OriginalWorkQuote<'r>,observed:u64,additional:u64)->OriginalWorkQuoteComplete<'r>where 'b:'a{self.quotes.store(additional,Ordering::Relaxed);reply.complete(Ok(observed.checked_add(additional).is_some_and(|n|n<=self.maximum)))}
 fn settle_partial<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,reply:OriginalWorkPartialCheck<'r>)->OriginalWorkPartialCheckComplete<'r>where 'b:'a{reply.complete(OriginalWorkRecipient::validate_context(self,c))}
 fn recover_partial<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,reply:OriginalWorkPartialCheck<'r>)->OriginalWorkPartialCheckComplete<'r>where 'b:'a{reply.complete(OriginalWorkRecipient::validate_context(self,c))}
}
impl OriginalConstructionRecipient for Port{
 bound!();
 fn submitted<'a,'b>(&self,_:&Self::Context<'a,'b>)->RetainedCloneProgress where 'b:'a{self.submitted}
 fn grant<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,reply:OriginalConstructionGrant<'r>)->OriginalConstructionGrantComplete<'r>where 'b:'a{let d=reply.demand();let complete=reply.complete(Ok(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}));if self.quote_unwind{self.quote_unwind=false;std::hint::black_box(&complete);panic!("recorded physical quote interrupted")}complete}
 fn accept<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,reply:OriginalConstructionAccept<'r>)->OriginalConstructionAcceptComplete<'r>where 'b:'a{let result=self.submitted.checked_add(reply.progress()).map(|next|self.submitted=next);let posts=self.posts.fetch_add(1,Ordering::Relaxed)+1;let completed=reply.complete(result);if self.post_unwind&&posts==2{self.post_unwind=false;std::hint::black_box(&completed);panic!("recorded reply Post interrupted")}completed}
}
struct Check{source:OriginalSourceTurnIdentity,mode:String,calls:Arc<AtomicUsize>,recoveries:Arc<AtomicUsize>}
impl OriginalRecordedProducer for Check{
 type Request=OriginalCheckpointRequest;type Reply=bool;bound!();
 fn receive<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,_:Self::Request,reply:OriginalRecordedReply<'r,bool>)->Result<OriginalRecordedReplyComplete<'r,bool>,ValueError>where 'b:'a{let call=self.calls.fetch_add(1,Ordering::Relaxed)+1;if self.mode=="checkpointPending"{return Ok(reply.pending())}if self.mode=="checkpointRefusal"{return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::Canceled,"actual checkpoint refusal"))))}let complete=reply.complete(Ok(self.mode!="checkpointCancel"&&!(self.mode=="replyCheckpointCancel"&&call==2)));if self.mode=="checkpointUnwind"{std::hint::black_box(&complete);panic!("recorded checkpoint interrupted")}Ok(complete)}
 fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,_:Self::Request,reply:OriginalRecordedReply<'r,bool>)->Result<OriginalRecordedReplyComplete<'r,bool>,ValueError>where 'b:'a{self.recoveries.fetch_add(1,Ordering::Relaxed);Ok(reply.complete(Ok(true)))}
}
struct Span{source:OriginalSourceTurnIdentity}
impl OriginalRecordedProducer for Span{
 type Request=OriginalSpanRequest;type Reply=();bound!();
 fn receive<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,_:Self::Request,reply:OriginalRecordedReply<'r,()>)->Result<OriginalRecordedReplyComplete<'r,()>,ValueError>where 'b:'a{Ok(reply.complete(Ok(())))}
 fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,_:Self::Request,reply:OriginalRecordedReply<'r,()>)->Result<OriginalRecordedReplyComplete<'r,()>,ValueError>where 'b:'a{Ok(reply.pending())}
}
struct Bytes{source:OriginalSourceTurnIdentity,input:[u8;5],output:[u8;5],position:usize,calls:usize,recoveries:usize,pending:bool,unwind:bool}
impl Bytes{
 fn copy_into<'r>(&mut self,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,NativeEncodeProducerOutcome,NativeEncodeProducerFailure>,end:usize)->Result<OriginalEffectReplyComplete<'r,NativeEncodeProducerOutcome,NativeEncodeProducerFailure>,ValueError>{while self.position<end{assert!(effect.performed(1)?);self.output[self.position]=self.input[self.position];self.position+=1;}if self.position<self.input.len(){return Ok(reply.pending())}let complete=reply.complete(Ok(NativeEncodeProducerOutcome{performed:true,progress:RetainedCloneProgress{copied_items:1,copied_bytes:5,..Default::default()}}));if self.unwind{self.unwind=false;std::hint::black_box(&complete);panic!("recorded byte producer interrupted")}Ok(complete)}
}
impl OriginalEffectProducer for Bytes{
 type Output=NativeEncodeProducerOutcome;type Failure=NativeEncodeProducerFailure;bound!();
 fn receive<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.calls+=1;self.copy_into(effect,reply,if self.pending{2}else{5})}
 fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.recoveries+=1;self.copy_into(effect,reply,5)}
}
